-- 002_import_all_envelope_parties.sql
-- Populates all 1,836 MARG ERP parties into B2B PostgreSQL database
-- Includes GPS coordinates, route, contact, and GSTIN

ON CONFLICT (party_code) DO UPDATE SET
  party_name = EXCLUDED.party_name,
  mobile = COALESCE(EXCLUDED.mobile, parties.mobile),
  address = EXCLUDED.address,
  city = EXCLUDED.city,
  area = EXCLUDED.area,
  latitude = COALESCE(EXCLUDED.latitude, parties.latitude),
  longitude = COALESCE(EXCLUDED.longitude, parties.longitude);

